/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (txb_isur_cd.getValue() === "" || txb_isur_cd.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "법인코드(명)"));
        txb_isur_cd.focus();
        return;
    }
    const delib = $c.cp.valueOfIndex(delib_step_tp_cd, "VALUE", delib_step_tp_cd.getSelectedIndex());
    if (delib.length < 1) {
        await $c.win.alert("[심의단계]를 선택하세요.");
        delib_step_tp_cd.focus();
        return;
    }
    if (comite_dd.getValue() === "") {
        await $c.win.alert("[위원회 일자]를 입력하세요.");
        comite_dd.focus();
        return;
    }
    if (file_name.getValue() === "" || file_name.getValue().indexOf(" ") === "") {
        await $c.win.alert("[첨부파일]은 반드시 첨부하셔야합니다.");
        file_name.focus();
        return;
    }
    const rtn = confirm('위사항을 입력 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        reg_emp_no.setValue(js_id);
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/RealInvstgImpr.do",
            ref : "dts_registerRealInvstgImpr,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name setInfoHeader
 * @description set Info Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setInfoHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_registerRealInvstgImpr",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_registerRealInvstgImpr=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_registerRealInvstgImpr.insertRow();
};

/**
 * @method
 * @name filedown
 * @description 파일 다운로드
 * @param {*} attach_seq attach_seq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(attach_seq) {
    location.href = "/filedownload.do?REAL_INVSTG_IMPR_SEQ=" + scwin.real_invstg_impr_seq + "&ATTACH_SEQ=" + attach_seq + "&gubun=63";
};

/**
 * @method
 * @name checkMaxLength
 * @description check Max Length 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength = async function(obj, size, lbl) {
    const overLen = ($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkFileSize
 * @description check File Size 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkFileSize = function() {
    const maxFileSize = 1024 * 1024 * 50; // 50MB
    const mySize = inf_find.fileInfo("size");
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
};

/**
 * @method
 * @name trs_Read_OnSuccess
 * @description Read On Success 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Read_OnSuccess = function() {

};

/**
 * @method
 * @name trs_Read_OnFail
 * @description Read On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Read_OnFail = async function() {
    await $c.win.alert(trs_Read.ErrorMsg);
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    let msg = trs_Save.ErrorMsg;
    if (msg === "T") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "개선계획의 주요내용 입력 "));
        $c.frame.path("../").fn_list_sync();
        await $c.win.closePopup();
    } else {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "개선계획의 주요내용 입력 "));
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    let msg = $c.stf.getMessageParam("MSG-A002", "개선계획의 주요내용 입력 ");
};

/**
 * @method
 * @name save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save_onclick = async function() {
    await scwin.save();
};

/**
 * @method
 * @name cancel_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cancel_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    const filenm = file_name.getValue();
    dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
    file_name.setValue(inf_find.getValue());
    if (inf_find.getValue() === "") {
        file_name.setValue(filenm);
    }
};

scwin.btn_lineadd_onclick = async function() {
if (scwin.real_invstg_impr_seq !== "input") {
    scwin.fileRowcount = dts_fileList.getRowCount();
}
scwin.fileRowcount++;
if (scwin.fileRowcount >= 2) {
    await $c.win.alert("더이상 추가하실수 없습니다.");
    scwin.fileRowcount = 1;
} else {
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() !== "") {
        const fileName = inf_find.getValue();
        if (filename.indexOf('\') > 0) {,fileName=filename.substring(filename.lastIndexOf('\
                ')+1);,txb_filenmsize.setValue(fileName), ( !$c.stf.checkMaxLength(txb_filenmsize,80,"파일명") ) ,{dts_fileList : dts_fileList , txb_filenmsize : txb_filenmsize , return : return}, ( !scwin.checkFileSize() ) ,{alert : function([object Object]){

                $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
                return;
            }
        }, dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue()), file_name.setValue(inf_find.getValue()))), {
    dts_fileList: dts_fileList,
    txb_filenmsize: txb_filenmsize
}))
function btn_linedelete_onclick() {
    if (scwin.fileRowcount > 0) scwin.fileRowcount--;
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};

function grd_fileList_OnDblClick(row, colid) {
    if (row == 0) return;
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        scwin.filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
    }
};

function Grd_com_isur_OnKeyPress(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};

function Grd_com_isur_OnDblClick(row, colid) {
    $c.cm.fn_com_Confirm_set();
};

function Grd_com_isur_OnClick(row, colid) {
    Grd_com_isur.style.display = "";
};

function Grd_com_isur_OnSetFocus() {
    stFocusGrid = true;
};

function Grd_com_isur_OnKillFocus() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

function txb_isur_cd_onblur() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};

function txb_isur_cd_onfocus() {
    Grd_com_isur.style.display = "none";
};

function txb_isur_cd_onkeyup() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};

function MxDataSet_com_isur_OnFilter(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};

function icn_SCal_onclick() {
    popUpCalendar2(comite_dd);
};

function gform_onload() {
    scwin.getCode();
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.real_invstg_impr_seq = $c.frame.path("../").scwin.real_invstg_impr_seq;
    $c.stf.showObj(file_name, false);
    $c.stf.showObj(belng_dep_cd, false);
    $c.stf.showObj(ld_mkt_tp_cd, false);
    $c.stf.showObj(txb_filenmsize, false);
    scwin.gClickId = $c.frame.path("../").clickId;

    //조회화면 onload
    if (scwin.gClickId != "input") {
        $c.stf.showObj(pnl_1, true);
        $c.stf.showObj(pnl_2, false);
        $c.stf.showObj(save, false);
        txb_isur_cd.setDisabled("true");
        img_com_srch.style.display = "none";
        scwin.singleRead();
    } else {
        //등록화면 onload
        scwin.setInfoHeader();
        //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인

        //fn_setFileDataHeader();
        scwin.fileRowcount = 0;
        reg_ddtm.setValue($c.ut.cGetToday("yyyymmdd"));
        reg_emp_no.setValue(js_emp_nm);
        belng_dep_cd.setValue(js_dep_cd);
        ld_mkt_tp_cd.setValue(js_market);
        $c.stf.showObj(pnl_1, false);
    }
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
}
}
};
